import subprocess

def get_last_login_records(username: str) -> str:
    """
    Query recent SSH login records for the given username
    using the `last` command and filtering with Python.
    """
    try:
        result = subprocess.run(
            ["last"],
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        return f"Error running 'last': {e.stderr.strip()}"
    except FileNotFoundError:
        return "Error: 'last' command not found on this system."

    lines = result.stdout.splitlines()
    filtered = [line for line in lines if username in line]

    if not filtered:
        return f"No login records found for user: {username}"

    return "\n".join(filtered)
